-- Schema captured read-only from documented synthetic Android 0.2.1 fixture.
-- Source release f384ecfe7a2b4fec5bfcc3d77bbae73762a10145. No ledger rows copied.
CREATE TABLE "categories" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), "category_kind" TEXT NULL, "parent_id" TEXT NULL, PRIMARY KEY ("id"), CHECK (length(id) BETWEEN 1 AND 64), CHECK (length(name) BETWEEN 1 AND 30), CHECK (typeof(sort_order) = 'integer'), CHECK (typeof(is_archived) = 'integer' AND is_archived IN (0, 1)));

CREATE TABLE "ledger_entries" ("id" TEXT NOT NULL, "amount_fen" INTEGER NOT NULL CHECK("amount_fen" > 0 AND "amount_fen" <= 99999999999), "kind" TEXT NOT NULL CHECK("kind" IN ('expense', 'income')), "occurred_local" TEXT NOT NULL, "occurred_at_utc_ms" INTEGER NOT NULL, "category_id" TEXT NOT NULL REFERENCES categories (id), "note" TEXT NOT NULL DEFAULT '', "created_at_utc_ms" INTEGER NOT NULL, "updated_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), CHECK (length(id) BETWEEN 1 AND 64), CHECK (length(category_id) BETWEEN 1 AND 64), CHECK (length(note) <= 500), CHECK (typeof(amount_fen) = 'integer'), CHECK (length(occurred_local) = 10 AND occurred_local GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr(occurred_local, 1, 4) BETWEEN '1900' AND '9999' AND substr(occurred_local, 6, 2) BETWEEN '01' AND '12' AND CAST(substr(occurred_local, 9, 2) AS INTEGER) BETWEEN 1 AND CASE WHEN substr(occurred_local, 6, 2) = '02' THEN 28 + (CAST(substr(occurred_local, 1, 4) AS INTEGER) % 4 = 0 AND (CAST(substr(occurred_local, 1, 4) AS INTEGER) % 100 != 0 OR CAST(substr(occurred_local, 1, 4) AS INTEGER) % 400 = 0)) WHEN substr(occurred_local, 6, 2) IN ('04', '06', '09', '11') THEN 30 ELSE 31 END), CHECK (typeof(occurred_at_utc_ms) = 'integer' AND occurred_at_utc_ms BETWEEN -8640000000000000 AND 8640000000000000), CHECK (typeof(created_at_utc_ms) = 'integer' AND created_at_utc_ms BETWEEN -8640000000000000 AND 8640000000000000), CHECK (typeof(updated_at_utc_ms) = 'integer' AND updated_at_utc_ms BETWEEN -8640000000000000 AND 8640000000000000), CHECK (updated_at_utc_ms >= created_at_utc_ms));

CREATE TABLE "monthly_budgets" ("month" TEXT NOT NULL, "amount_fen" INTEGER NOT NULL CHECK("amount_fen" >= 0 AND "amount_fen" <= 99999999999), "updated_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("month"), CHECK (typeof(amount_fen) = 'integer'), CHECK (length(month) = 7 AND month GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]' AND substr(month, 1, 4) BETWEEN '1900' AND '9999' AND substr(month, 6, 2) BETWEEN '01' AND '12'), CHECK (typeof(updated_at_utc_ms) = 'integer' AND updated_at_utc_ms BETWEEN -8640000000000000 AND 8640000000000000));

CREATE TABLE "personal_state" ("key" TEXT NOT NULL, "value_json" TEXT NOT NULL, PRIMARY KEY ("key"));

CREATE TABLE "recovery_snapshots" ("id" TEXT NOT NULL, "created_at_utc_ms" INTEGER NOT NULL, "payload" TEXT NOT NULL, PRIMARY KEY ("id"), CHECK (length(id) BETWEEN 1 AND 64), CHECK (typeof(created_at_utc_ms) = 'integer' AND created_at_utc_ms BETWEEN -8640000000000000 AND 8640000000000000));

CREATE INDEX ledger_entries_local_date ON ledger_entries(occurred_local, occurred_at_utc_ms, id);
